const std = @import("std");
const MOD: i64 = 998244353; const Q: usize = 16; const CAP: usize = 4096;
const Node = struct { sum:i64=0, mul:i64=1, add:i64=0, left:i32=-1, right:i32=-1 };
const Tree = struct {
 a:[CAP]Node = [_]Node{.{}} ** CAP, used:usize=0,
 fn norm(x:i64)i64{return @mod(x,MOD);}
 fn clone(t:*Tree,s:i32)i32{if(s<0 or t.used>=CAP)return -1;const d:i32=@intCast(t.used);t.a[t.used]=t.a[@intCast(s)];t.used+=1;return d;}
 fn make(t:*Tree,sum:i64,l:i32,r:i32)i32{if(t.used>=CAP)return -1;const d:i32=@intCast(t.used);t.a[t.used]=.{.sum=sum,.mul=1,.add=0,.left=l,.right=r};t.used+=1;return d;}
 fn apply(t:*Tree,x:i32,m0:i64,b0:i64,len:usize)void{const m=norm(m0);const b=norm(b0);const i:usize=@intCast(x);t.a[i].sum=norm(m*t.a[i].sum+b*@as(i64,@intCast(len)));t.a[i].mul=norm(m*t.a[i].mul);t.a[i].add=norm(m*t.a[i].add+b);}
 fn push(t:*Tree,x:i32,l:usize,r:usize)bool{const i:usize=@intCast(x);const m=t.a[i].mul;const b=t.a[i].add;if(m==1 and b==0)return true;if(l<r){const mid=l+(r-l)/2;const lc=clone(t,t.a[i].left);const rc=clone(t,t.a[i].right);if(lc<0 or rc<0)return false;t.a[i].left=lc;t.a[i].right=rc;t.apply(lc,m,b,mid-l+1);t.apply(rc,m,b,r-mid);}t.a[i].mul=1;t.a[i].add=0;return true;}
 fn build(t:*Tree,v:[]const i64,l:usize,r:usize)i32{if(l==r)return t.make(v[l],-1,-1);const mid=l+(r-l)/2;const x=t.build(v,l,mid);const y=t.build(v,mid+1,r);if(x<0 or y<0)return -1;return t.make(norm(t.a[@intCast(x)].sum+t.a[@intCast(y)].sum),x,y);}
 fn update(t:*Tree,root:i32,l:usize,r:usize,ql:usize,qr:usize,m:i64,b:i64)i32{if(ql<=l and r<=qr){const x=clone(t,root);if(x<0)return -1;t.apply(x,m,b,r-l+1);return x;}const x=clone(t,root);if(x<0 or !t.push(x,l,r))return -1;const mid=l+(r-l)/2;const xi:usize=@intCast(x);if(ql<=mid){const y=t.update(t.a[xi].left,l,mid,ql,qr,m,b);if(y<0)return -1;t.a[xi].left=y;}if(qr>mid){const y=t.update(t.a[xi].right,mid+1,r,ql,qr,m,b);if(y<0)return -1;t.a[xi].right=y;}t.a[xi].sum=norm(t.a[@intCast(t.a[xi].left)].sum+t.a[@intCast(t.a[xi].right)].sum);return x;}
 fn logicalChild(t:*Tree,s:i32,right:bool,l:usize,r:usize)i32{const si:usize=@intCast(s);const c=clone(t,if(right)t.a[si].right else t.a[si].left);if(c<0)return -1;const m=t.a[si].mul;const b=t.a[si].add;if(m!=1 or b!=0){const mid=l+(r-l)/2;t.apply(c,m,b,if(right)r-mid else mid-l+1);}return c;}
 fn copyRange(t:*Tree,dst:i32,src:i32,l:usize,r:usize,ql:usize,qr:usize)i32{if(ql<=l and r<=qr)return src;const x=clone(t,dst);if(x<0 or !t.push(x,l,r))return -1;const mid=l+(r-l)/2;const xi:usize=@intCast(x);if(ql<=mid){const s=t.logicalChild(src,false,l,r);if(s<0)return -1;const y=t.copyRange(t.a[xi].left,s,l,mid,ql,qr);if(y<0)return -1;t.a[xi].left=y;}if(qr>mid){const s=t.logicalChild(src,true,l,r);if(s<0)return -1;const y=t.copyRange(t.a[xi].right,s,mid+1,r,ql,qr);if(y<0)return -1;t.a[xi].right=y;}t.a[xi].sum=norm(t.a[@intCast(t.a[xi].left)].sum+t.a[@intCast(t.a[xi].right)].sum);return x;}
 fn query(t:*const Tree,x:i32,l:usize,r:usize,ql:usize,qr:usize,cm:i64,ca:i64)i64{const i:usize=@intCast(x);if(ql<=l and r<=qr)return norm(cm*t.a[i].sum+ca*@as(i64,@intCast(r-l+1)));const mid=l+(r-l)/2;const nm=norm(cm*t.a[i].mul);const na=norm(cm*t.a[i].add+ca);var z:i64=0;if(ql<=mid)z=t.query(t.a[i].left,l,mid,ql,qr,nm,na);if(qr>mid)z=norm(z+t.query(t.a[i].right,mid+1,r,ql,qr,nm,na));return z;}
};
fn validRef(k:i64,i:usize,kinds:[Q]i64)bool{return k == -1 or (k>=0 and @as(usize,@intCast(k))<i and (kinds[@intCast(k)]==0 or kinds[@intCast(k)]==1));}
fn put(out:[*]u8,at:usize,x:i64)void{const b:u64=@bitCast(x);for(0..8)|j|out[at+j]=@truncate(b>>@intCast(8*j));}
export fn persistent_range_affine_range_sum(input_opt:?[*]const i64,length:usize,output_opt:?[*]u8,capacity:usize)i64{
 const input=input_opt orelse return -1;if(length<2 or length>115)return -1;const n0=input[0];const q0=input[1];if(n0<1 or n0>16 or q0<1 or q0>16)return -1;const n:usize=@intCast(n0);const q:usize=@intCast(q0);var off=2+n;if(length<off)return -1;for(0..n)|j|if(input[2+j]<0 or input[2+j]>=MOD)return -1;
 var kind=[_]i64{0}**Q;var refs=[_]i64{0}**Q;var src=[_]i64{0}**Q;var ls=[_]i64{0}**Q;var rs=[_]i64{0}**Q;var mul=[_]i64{1}**Q;var add=[_]i64{0}**Q;
 for(0..q)|i|{if(off>=length)return -1;const op=input[off];const w:usize=if(op==0)6 else if(op==1)5 else if(op==2)4 else 0;if(w==0 or length-off<w)return -1;const k=input[off+1];if(!validRef(k,i,kind))return -1;kind[i]=op;refs[i]=k;if(op==0 or op==2){ls[i]=input[off+2];rs[i]=input[off+3];if(ls[i]<0 or rs[i]<=ls[i] or rs[i]>n0)return -1;}if(op==0){mul[i]=input[off+4];add[i]=input[off+5];if(mul[i]<1 or mul[i]>=MOD or add[i]<0 or add[i]>=MOD)return -1;}if(op==1){src[i]=input[off+2];ls[i]=input[off+3];rs[i]=input[off+4];if(!validRef(src[i],i,kind) or ls[i]<0 or rs[i]<=ls[i] or rs[i]>n0)return -1;}off+=w;}
 if(off!=length)return -1;var tree=Tree{};const initial=tree.build(input[2..2+n],0,n-1);if(initial<0)return -1;var roots=[_]i32{0}**Q;var ans=[_]i64{0}**Q;var na:usize=0;
 for(0..q)|i|{const base=if(refs[i]<0)initial else roots[@intCast(refs[i])];if(kind[i]==0){roots[i]=tree.update(base,0,n-1,@intCast(ls[i]),@intCast(rs[i]-1),mul[i],add[i]);if(roots[i]<0)return -1;}else if(kind[i]==1){const s=if(src[i]<0)initial else roots[@intCast(src[i])];roots[i]=tree.copyRange(base,s,0,n-1,@intCast(ls[i]),@intCast(rs[i]-1));if(roots[i]<0)return -1;}else{ans[na]=tree.query(base,0,n-1,@intCast(ls[i]),@intCast(rs[i]-1),1,0);na+=1;}}
 const bytes=8*na;const out=output_opt orelse return -2;if(capacity<bytes)return -2;for(0..na)|i|put(out,8*i,ans[i]);return @intCast(bytes);
}
